package main

import (
	"fmt"
	"math/rand"

	"github.com/cometbft/cometbft/internal/bits"
	cmtrand "github.com/cometbft/cometbft/internal/rand"
)

func main() {
	// Test NewStdlibRand function
	r := cmtrand.NewStdlibRand()
	if r == nil {
		fmt.Println("ERROR: NewStdlibRand returned nil")
		return
	}
	fmt.Println("✓ NewStdlibRand works correctly")

	// Test that it returns *rand.Rand
	_ = rand.Intn(10) // Just to make sure rand package is imported

	// Test BitArray.PickRandom with provided rand
	ba := bits.NewBitArray(100)
	ba.SetIndex(10, true)
	ba.SetIndex(50, true)
	ba.SetIndex(90, true)

	idx, ok := ba.PickRandom(r)
	if !ok {
		fmt.Println("ERROR: PickRandom failed on non-empty bit array")
		return
	}
	if idx != 10 && idx != 50 && idx != 90 {
		fmt.Printf("ERROR: PickRandom returned unexpected index: %d\n", idx)
		return
	}
	fmt.Printf("✓ BitArray.PickRandom works correctly (got index: %d)\n", idx)

	// Test with empty bit array
	emptyBA := bits.NewBitArray(100)
	_, ok = emptyBA.PickRandom(r)
	if ok {
		fmt.Println("ERROR: PickRandom should return false for empty bit array")
		return
	}
	fmt.Println("✓ BitArray.PickRandom correctly handles empty bit array")

	// Test with nil bit array
	var nilBA *bits.BitArray
	_, ok = nilBA.PickRandom(r)
	if ok {
		fmt.Println("ERROR: PickRandom should return false for nil bit array")
		return
	}
	fmt.Println("✓ BitArray.PickRandom correctly handles nil bit array")

	fmt.Println("\nAll tests passed!")
}
